//! Database seeder binary for module: pos
//!
//! Generated by metaphor-schema. Do not edit manually.
//!
//! Run with: cargo run --bin pos-seeder
//! Or via CLI: backbone seed run --module pos
//!
//! This binary runs all registered seeders in order.

use anyhow::Result;
use sqlx::postgres::PgPoolOptions;
use std::env;

// Import seeders
use backbone_pos::seeders::SeedPosClosingEntrySeeder;
use backbone_pos::seeders::SeedPosInvoiceSeeder;
use backbone_pos::seeders::SeedPosInvoiceItemSeeder;
use backbone_pos::seeders::SeedPosPaymentSeeder;
use backbone_pos::seeders::SeedPosProfileSeeder;
use backbone_pos::seeders::SeedPosOpeningEntrySeeder;
use backbone_pos::seeders::SeedPosCashMovementSeeder;
use backbone_pos::seeders::SeedPosDiscountSeeder;
use backbone_pos::seeders::SeedPosManagerPinSeeder;
use backbone_pos::seeders::SeedPosFloorPlanSeeder;
use backbone_pos::seeders::SeedPosTableSeeder;
use backbone_pos::seeders::Seeder;

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    let force = args.iter().any(|a| a == "--force");
    let filter: Option<&str> = args.iter()
        .skip(1)
        .find(|a| !a.starts_with("-"))
        .map(|s| s.as_str());

    let database_url = env::var("DATABASE_URL")
        .map_err(|e| anyhow::anyhow!("DATABASE_URL must be set: {e}"))?;

    println!("Connecting to database...");

    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(&database_url)
        .await?;

    println!("Connected to database");
    println!();
    println!("Running seeders for module: pos");
    println!();

    // Register seeders in order
    let mut seeders: Vec<Box<dyn Seeder + Send + Sync>> = Vec::new();
    seeders.push(Box::new(SeedPosClosingEntrySeeder::new()));
    seeders.push(Box::new(SeedPosInvoiceSeeder::new()));
    seeders.push(Box::new(SeedPosInvoiceItemSeeder::new()));
    seeders.push(Box::new(SeedPosPaymentSeeder::new()));
    seeders.push(Box::new(SeedPosProfileSeeder::new()));
    seeders.push(Box::new(SeedPosOpeningEntrySeeder::new()));
    seeders.push(Box::new(SeedPosCashMovementSeeder::new()));
    seeders.push(Box::new(SeedPosDiscountSeeder::new()));
    seeders.push(Box::new(SeedPosManagerPinSeeder::new()));
    seeders.push(Box::new(SeedPosFloorPlanSeeder::new()));
    seeders.push(Box::new(SeedPosTableSeeder::new()));

    // Sort by order
    seeders.sort_by_key(|s| s.order());

    // Run seeders
    for seeder in &seeders {
        let name = seeder.name();

        // Apply filter if specified
        if let Some(f) = filter {
            if !name.contains(f) {
                continue;
            }
        }

        if force {
            println!("   Running {}...", name);
            seeder.run(&pool).await?;
            println!("   {} completed", name);
        } else {
            println!("   Checking {}...", name);
            if seeder.should_run(&pool).await? {
                println!("   Running {}...", name);
                seeder.run(&pool).await?;
                println!("   {} completed", name);
            } else {
                println!("   {} already applied, skipping", name);
            }
        }
    }

    println!();
    println!("All seeders completed successfully!");

    Ok(())
}
